<script setup lang="ts">import {onMounted,ref} from 'vue';const projects=ref<any[]>([]);const name=ref('');const error=ref('');const load=async()=>{const r=await fetch('/api/v1/projects');if(r.ok)projects.value=await r.json()};const create=async()=>{if(!name.value.trim())return;const r=await fetch('/api/v1/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.value})});if(r.ok){name.value='';await load()}else error.value='Não foi possível criar o projeto.'};onMounted(load)</script>
<template><div class="hero"><div><p class="kicker">WORKSPACES</p><h1>Projects</h1><p class="muted">Keep applications grouped by purpose.</p></div></div><form class="inline-form" @submit.prevent="create"><input v-model="name" placeholder="Project name" aria-label="Project name" /><button class="primary">Create project</button></form><p class="error">{{error}}</p><div v-if="projects.length" class="project-list"><RouterLink v-for="project in projects" :key="project.id" :to="`/projects/${project.id}`" class="project-link"><article><strong>{{project.name}}</strong><span class="pill">{{project.status}}</span><p class="muted">{{project.description||project.slug}}</p></article></RouterLink></div><div v-else class="empty"><h2>No projects yet</h2><p>Your first project will appear here.</p></div></template>
